var hihat = synth.def((p, e, t, o) =&gt; (Math.random() - .5) * e.value, {release: .04, duration: 0, amp: .4});
var cymbal = synth.def((p, e, t, o) =&gt; (Math.random() - .5) * e.value, {release: .2, duration: 0, amp: .4});

